from pathlib import Path
import json,html,re
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
plt.rcParams.update({'figure.facecolor':'#0a111b','axes.facecolor':'#0a111b','savefig.facecolor':'#0a111b','text.color':'#e5edf6','axes.labelcolor':'#b5c5d7','xtick.color':'#b5c5d7','ytick.color':'#b5c5d7','axes.edgecolor':'#486077','font.family':'DejaVu Sans','font.size':10,'svg.hashsalt':'ps-oct30','axes.spines.top':False,'axes.spines.right':False})
CSS='''*{box-sizing:border-box}body{margin:0;background:#0a111b;color:#e5edf6;font:16px/1.65 Arial,sans-serif}a{color:#8bc9ff;text-underline-offset:4px}a:hover{color:white}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #8bc9ff;outline-offset:4px}.skip{position:absolute;left:12px;top:-60px}.skip:focus{top:8px}header,main,footer{max-width:1120px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #2b3d52}.eyebrow{color:#8bc9ff;text-transform:uppercase;letter-spacing:.12em;font-size:12px}h1{font:400 clamp(38px,6vw,72px)/1.05 Georgia,serif;max-width:920px;margin:24px 0}h2{font:400 32px/1.15 Georgia,serif;margin-top:42px}h3{font-size:18px}p{max-width:82ch}.intro{font-size:20px;color:#c0d0df;max-width:75ch}.section{border-top:1px solid #2b3d52;padding:12px 0 32px}.note{border-left:3px solid #75bafa;padding:12px 18px;background:#111e2b;max-width:90ch}.numbers{display:flex;gap:36px;flex-wrap:wrap;padding:20px 0}.numbers strong{display:block;font-size:34px;font-weight:400}.numbers span{color:#b5c5d7;font-size:14px}.tablewrap{overflow-x:auto}table{border-collapse:collapse;min-width:440px;width:100%;font-size:14px}td,th{padding:10px 12px;text-align:left;border-bottom:1px solid #2b3d52}th{color:#9acfff}.chart{margin:30px 0}.chart svg{width:100%;height:auto;display:block}figcaption{font-size:13px;color:#b5c5d7}.formgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}label{display:block;color:#bed1e4}input,select,button{display:block;width:100%;padding:11px;border:1px solid #516a84;background:#101d2b;color:#e5edf6;font:inherit}button{width:auto;cursor:pointer;background:#213f5b;margin:20px 0}.results{padding:20px 0}.warn{color:#ffd28a}footer{font-size:13px;color:#a9bed2;border-top:1px solid #2b3d52}.trajectory{width:100%;height:auto}details{padding:16px 0}summary{cursor:pointer;color:#8bc9ff}@media(max-width:720px){header,main,footer{padding:20px}.formgrid{grid-template-columns:1fr}h1{font-size:42px}.numbers{gap:22px}table{font-size:13px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'''
def dump(p,obj):p.write_text(json.dumps(obj,indent=2,allow_nan=False)+'\n')
def table(df,digits=2):return '<div class="tablewrap">'+df.to_html(index=False,border=0,float_format=lambda x:f'{x:,.{digits}f}',escape=True)+'</div>'
def figure(out,name,caption):
 s=(out/(name+'.svg')).read_text();s=s[s.index('<svg'):];s=re.sub(r'id="([^"]+)"',lambda m:'id="'+name+'-'+m[1]+'"',s);s=re.sub(r'(url\(#|href="#)([^)" ]+)',lambda m:m[1]+name+'-'+m[2],s)
 s=s.replace('<svg ', '<svg role="img" aria-label="'+html.escape(caption,quote=True)+'" ',1)
 return '<figure class="chart">'+s+'<figcaption>'+html.escape(caption)+'</figcaption></figure>'
def savefig(out,name,fig):fig.savefig(out/(name+'.svg'),bbox_inches='tight',metadata={'Date':None});plt.close(fig)
def page(root,name,title,subtitle,body,script='',data=None):
 payload='<script id="model-data" type="application/json">'+json.dumps(data,allow_nan=False).replace('</',r'<\/')+'</script>' if data is not None else ''
 s='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' | Prathamesh Singh</title><style>'+CSS+'</style></head><body><a class="skip" href="#main">Skip to content</a><header><a href="https://prathameshsingh.com">Prathamesh Singh</a><a href="report.html" '+('aria-current="page"' if name=='report.html' else '')+'>Research</a><a href="workbench.html" '+('aria-current="page"' if name=='workbench.html' else '')+'>Decision tool</a></header><main id="main"><p class="eyebrow">Independent analysis / October 2026</p><h1>'+html.escape(title)+'</h1><p class="intro">'+html.escape(subtitle)+'</p>'+body+'</main><footer>Prathamesh Singh · Reproducible public-data research. Hypothetical business inputs are identified separately. <a href="https://github.com/Pratattack/analytics-portfolio/tree/main/'+'projects/2026-10-30/'+root.name+'">Source</a></footer>'+payload+('<script>'+script+'</script>' if script else '')+'</body></html>'
 # Source path is explicit and independent of machine path.
 slug=root.name;s=re.sub(r'https://github.com/Pratattack/analytics-portfolio/tree/main/[^"<>]+', 'https://github.com/Pratattack/analytics-portfolio/tree/main/projects/2026-10-30/'+slug,s)
 (root/'outputs'/name).write_text(s)
